            try {
                const btn = document.querySelector('.submit-btn');
                const originalText = btn.innerHTML;
                btn.innerHTML = 'CONNECTING TO NEURAL NET...';

                setTimeout(() => {
                    if (window.triggerSlash) {
                        triggerSlash(`/send ${startMessage}|/trigger`);
                    } else {
                        console.log('Environment not supported, message:', startMessage);
                        alert('已生成档案：\n' + startMessage);
                        btn.innerHTML = originalText; 
                    }
                }, 800);
            } catch (error) {
                console.error('Failure:', error);
                alert('Connection Lost');
            }
        }
    </script>
